cat <<'EOF' > app/javascript/controllers/option_rows_controller.js
import { Controller } from "@hotwired/stimulus"

export default class extends Controller {
  static targets = ["list", "row"]

  add() {
    const idx = this.rowTargets.length
    const num = idx + 1

    const row = document.createElement("div")
    row.className = "option-row"
    row.dataset.optionRowsTarget = "row"

    const bodyLabel = document.createElement("label")
    bodyLabel.className = "visually-hidden"
    bodyLabel.htmlFor = `question_option_rows_${idx}_body`
    bodyLabel.textContent = `Option ${num}`

    const bodyInput = document.createElement("input")
    bodyInput.className = "input"
    bodyInput.type = "text"
    bodyInput.name = `question[option_rows][${idx}][body]`
    bodyInput.id = `question_option_rows_${idx}_body`
    bodyInput.placeholder = `Option ${num}`

    const checkboxWrap = document.createElement("span")
    checkboxWrap.className = "checkbox"

    const hiddenInput = document.createElement("input")
    hiddenInput.type = "hidden"
    hiddenInput.name = `question[option_rows][${idx}][correct]`
    hiddenInput.value = "0"

    const checkboxInput = document.createElement("input")
    checkboxInput.type = "checkbox"
    checkboxInput.name = `question[option_rows][${idx}][correct]`
    checkboxInput.id = `question_option_rows_${idx}_correct`
    checkboxInput.value = "1"
    checkboxInput.setAttribute("aria-label", `Option ${num} is correct`)

    const checkboxLabel = document.createElement("label")
    checkboxLabel.className = "visually-hidden"
    checkboxLabel.htmlFor = `question_option_rows_${idx}_correct`
    checkboxLabel.textContent = `Option ${num} is correct`

    const correctText = document.createElement("span")
    correctText.setAttribute("aria-hidden", "true")
    correctText.dataset.action = "click->option-rows#toggleCorrect"
    correctText.textContent = "Correct"

    checkboxWrap.append(hiddenInput, checkboxInput, checkboxLabel, correctText)

    const removeBtn = document.createElement("button")
    removeBtn.type = "button"
    removeBtn.className = "btn btn--danger btn--icon"
    removeBtn.setAttribute("aria-label", "Remove option")
    removeBtn.title = "Remove option"
    removeBtn.dataset.action = "option-rows#remove"
    removeBtn.textContent = "✕"

    row.append(bodyLabel, bodyInput, checkboxWrap, removeBtn)
    this.listTarget.appendChild(row)
    bodyInput.focus()
  }

  remove(event) {
    const row = event.currentTarget.closest("[data-option-rows-target='row']")
    if (row) {
      row.remove()
      this.renumber()
    }
  }

  toggleCorrect(event) {
    const checkbox = event.currentTarget.closest(".checkbox")?.querySelector('input[type="checkbox"]')
    if (checkbox) {
      checkbox.checked = !checkbox.checked
    }
  }

  renumber() {
    this.rowTargets.forEach((row, idx) => {
      const num = idx + 1
      const bodyLabel = row.querySelector("label[for$='_body']")
      const bodyInput = row.querySelector("input[type='text']")
      const hiddenInput = row.querySelector("input[type='hidden']")
      const checkboxInput = row.querySelector("input[type='checkbox']")
      const checkboxLabel = row.querySelector("label[for$='_correct']")

      if (bodyLabel) {
        bodyLabel.htmlFor = `question_option_rows_${idx}_body`
        bodyLabel.textContent = `Option ${num}`
      }
      if (bodyInput) {
        bodyInput.id = `question_option_rows_${idx}_body`
        bodyInput.name = `question[option_rows][${idx}][body]`
        bodyInput.placeholder = `Option ${num}`
      }
      if (hiddenInput) {
        hiddenInput.name = `question[option_rows][${idx}][correct]`
      }
      if (checkboxInput) {
        checkboxInput.id = `question_option_rows_${idx}_correct`
        checkboxInput.name = `question[option_rows][${idx}][correct]`
        checkboxInput.setAttribute("aria-label", `Option ${num} is correct`)
      }
      if (checkboxLabel) {
        checkboxLabel.htmlFor = `question_option_rows_${idx}_correct`
        checkboxLabel.textContent = `Option ${num} is correct`
      }
    })
  }
}
EOF

cat <<'EOF' > app/javascript/controllers/preview_controller.js
import { Controller } from "@hotwired/stimulus"

export default class extends Controller {
  static values = { questions: Array }
  static targets = ["stage"]

  connect() {
    if (this.questionsValue.length > 0) {
      this.restart()
    }
  }

  restart() {
    this.currentIndex = 0
    this.score = 0
    this.renderQuestion()
  }

  renderQuestion() {
    this.answered = false
    const total = this.questionsValue.length
    const question = this.questionsValue[this.currentIndex]

    this.stageTarget.replaceChildren()

    const numEl = document.createElement("div")
    numEl.className = "play-question__num"
    numEl.textContent = `Question ${this.currentIndex + 1} of ${total}`

    const bodyEl = document.createElement("div")
    bodyEl.className = "play-question__body"
    bodyEl.textContent = question.body

    const optionsEl = document.createElement("div")
    optionsEl.className = "play-options"

    question.options.forEach((option, idx) => {
      const btn = document.createElement("button")
      btn.type = "button"
      btn.className = "play-option"
      btn.dataset.index = idx

      const letterEl = document.createElement("span")
      letterEl.className = "play-option__letter"
      letterEl.textContent = idx < 26 ? String.fromCharCode(65 + idx) : String(idx + 1)

      const titleEl = document.createElement("span")
      titleEl.className = "play-option__title"
      titleEl.textContent = option.body

      const markEl = document.createElement("span")
      markEl.className = "play-option__mark"

      btn.append(letterEl, titleEl, markEl)
      btn.addEventListener("click", () => this.pickOption(idx, optionsEl))
      optionsEl.appendChild(btn)
    })

    this.stageTarget.append(numEl, bodyEl, optionsEl)
  }

  pickOption(pickedIdx, optionsEl) {
    if (this.answered) return
    this.answered = true

    const question = this.questionsValue[this.currentIndex]
    const total = this.questionsValue.length
    const pickedOption = question.options[pickedIdx]

    optionsEl.classList.add("is-locked", "is-revealed")

    const buttons = optionsEl.querySelectorAll(".play-option")
    buttons.forEach((btn, idx) => {
      btn.disabled = true
      const opt = question.options[idx]
      if (idx === pickedIdx) {
        btn.classList.add("is-picked")
      }
      if (opt.correct) {
        btn.classList.add("is-correct")
        const markEl = btn.querySelector(".play-option__mark")
        if (markEl) markEl.textContent = "✓"
      }
    })

    const statusEl = document.createElement("div")
    if (pickedOption.correct) {
      this.score += 1
      statusEl.className = "play-status play-status--right"
      statusEl.textContent = "Correct!"
    } else {
      statusEl.className = "play-status play-status--wrong"
      statusEl.textContent = "Wrong!"
    }

    const actionsEl = document.createElement("div")
    actionsEl.className = "buttons"
    actionsEl.style.marginTop = "20px"
    actionsEl.style.justifyContent = "center"

    const nextBtn = document.createElement("button")
    nextBtn.type = "button"
    nextBtn.className = "btn btn--pink"
    if (this.currentIndex < total - 1) {
      nextBtn.textContent = "Next question"
      nextBtn.addEventListener("click", () => this.next())
    } else {
      nextBtn.textContent = "See score"
      nextBtn.addEventListener("click", () => this.finish())
    }

    actionsEl.appendChild(nextBtn)
    this.stageTarget.append(statusEl, actionsEl)
  }

  next() {
    this.currentIndex += 1
    this.renderQuestion()
  }

  finish() {
    const total = this.questionsValue.length
    this.stageTarget.replaceChildren()

    const card = document.createElement("div")
    card.className = "card result-card"

    const scoreEl = document.createElement("div")
    scoreEl.className = "result-card__score"
    scoreEl.textContent = `Score: ${this.score}/${total}`

    const actionsEl = document.createElement("div")
    actionsEl.className = "buttons"
    actionsEl.style.marginTop = "24px"
    actionsEl.style.justifyContent = "center"

    const restartBtn = document.createElement("button")
    restartBtn.type = "button"
    restartBtn.className = "btn btn--pink"
    restartBtn.textContent = "Start over"
    restartBtn.addEventListener("click", () => this.restart())

    actionsEl.appendChild(restartBtn)
    card.append(scoreEl, actionsEl)
    this.stageTarget.appendChild(card)
  }
}
EOF

